 * Serializes a request body for use in a Swagger "try it out" request.
 *
 * The Swagger UI hands us a variety of body types depending on the operation
 * (JSON strings, url-encoded forms, multipart form data, binary uploads, ...).
 * The Bruno proxy that actually sends the request can only forward text-based
 * bodies, so anything binary/multipart is rejected with a helpful error rather
 * than being silently mangled.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

/**
 * Builds a human-readable message explaining that a body type can't be sent
 * from the "try it out" panel yet.
 *
 * @param {string} bodyTypeName - A human friendly description of the body type.
 * @returns {string}
 */
export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. ` +
  `The Swagger "try it out" panel can only send JSON, URL-encoded forms, plain text, ` +
  `and other text-based request bodies. Create a Bruno request if you need to send this kind of body.`;

/**
 * Creates a TypeError describing an unsupported body type.
 *
 * @param {string} label - Human friendly description used in the message.
 * @param {string} bodyType - Constructor name of the offending value.
 * @returns {TypeError}
 */
const unsupportedBodyError = (label, bodyType) => {
  const error = new TypeError(UNSUPPORTED_BODY_MESSAGE(label));
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

/**
 * @param {*} body - The request body provided by Swagger UI.
 * @returns {undefined | string}
 */
export const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
    return body.toString();
  }

  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    throw unsupportedBodyError('Multipart form data', 'FormData');
  }

  // `File` extends `Blob`, so it must be checked first to report the more specific type.
  if (typeof File !== 'undefined' && body instanceof File) {
    throw unsupportedBodyError('File upload', 'File');
  }

  if (typeof Blob !== 'undefined' && body instanceof Blob) {
    throw unsupportedBodyError('Binary file upload', 'Blob');
  }

  if (body instanceof ArrayBuffer) {
    throw unsupportedBodyError('Binary data', 'ArrayBuffer');
  }

  // Catches TypedArray (Uint8Array, Int16Array, ...) and DataView views over a buffer.
  if (ArrayBuffer.isView(body)) {
    throw unsupportedBodyError('Binary data', body.constructor.name);
  }

  // Any other object type is unsupported; report its constructor name.
  const bodyType = body.constructor?.name || 'Object';
  throw unsupportedBodyError(bodyType, bodyType);
};

export default serializeBody;
