const proxySwaggerFetch = async (payload) => {
  if (!payload || !payload.url) {
    return { error: true, code: 'INVALID_REQUEST' };
  }

  const { url, method, headers, body } = payload;

  try {
    const response = await axios({
      url,
      method,
      headers,
      data: body,
      responseType: 'arraybuffer',
      // Accept every status code so non-2xx responses are returned to the caller
      // rather than being thrown as errors.
      validateStatus: () => true
    });

    // In axios v1 the headers are an `AxiosHeaders` instance; normalize to a
